const serviceStyles = document.createElement('link');
serviceStyles.rel = 'stylesheet';
serviceStyles.href = 'service.css';
document.head.append(serviceStyles);

const services = {
  microblading:{name:'Microblading',headline:'Fine hair-stroke brows that look like your own.',intro:'Microblading uses a handheld tool to create ultra-fine, hair-like strokes that follow your natural growth pattern. It is for sparse, patchy or over-plucked brows when you want a soft, realistic finish.',ideal:'Normal to dry skin, thin or gappy brows, and a natural feathery effect.',process:'Consultation and brow mapping for symmetry, arch and length; pigment matching; numbing; then stroke work. Sessions generally take 2 to 3 hours.',healing:'Brows can look darker for 7 to 10 days, then soften. Expect light flaking in week one, a soft phase around weeks 2 to 3 and a perfecting session at 6 to 8 weeks. Results generally last 12 to 18 months.',caution:'Very oily or textured skin can be better suited to ombre or combination brows. It is not suitable during pregnancy, breastfeeding or chemotherapy.',image:'assets/brows-before-after.png'},
  ombre:{name:'Ombre Powder Brows',headline:'Soft, brushed-on definition, like brow makeup that never fades overnight.',intro:'Ombre brows use tiny dots of pigment to create a soft powdered gradient—lighter at the front and gently defined through the tail.',ideal:'Oily or combination skin, mature skin, or anyone who likes a defined, filled-in brow.',process:'Brow mapping and shape approval, pigment selection, numbing and softly layered shading.',healing:'Brows look stronger in the first week and settle around 30 to 40 percent lighter once healed. Results generally last 18 to 36 months, with a perfecting session at 6 to 8 weeks.',caution:'A consultation confirms your skin suitability, pigment choice and preferred level of definition.',image:'assets/gallery-3.jpeg'},
  combination:{name:'Combination Brows',headline:'Strokes for realism. Shading for depth. The best of both.',intro:'Combination brows blend delicate hair strokes at the front with soft powder shading through the body and tail for natural-looking hairs and added fullness.',ideal:'Most skin types, brows with gaps or thin tails, and anyone wanting definition with a softer front.',process:'Shape mapping and approval, pigment matching, numbing, then controlled strokes and shading in layers.',healing:'Results typically last 18 to 24 months. A perfecting session refines the healed shape and colour.',caution:'A consultation determines the technique that suits your skin best.',image:'assets/gallery-4.png'},
  'lip-blush':{name:'Lip Blush',headline:'Your lips, only softer, fuller-looking and always tinted.',intro:'Lip blush adds a soft, sheer wash of colour to define shape, balance asymmetry and brighten a flat or pale lip. There is no hard liner—just a fresh tint that fades gracefully.',ideal:'Pale or uneven lips, lost definition with age, and anyone tired of reapplying lip colour.',process:'Lip mapping, undertone-led shade testing, numbing and layered pigment. Lips can look swollen and intense for 1 to 3 days before softening.',healing:'A perfecting session follows at 6 to 8 weeks. Results typically last 2 to 3 years and fade gradually.',caution:'If you are prone to cold sores, tell us at booking. Preventive medication from your doctor may be needed.',image:'assets/lip-blush.jpg'},
  'dark-lip':{name:'Dark Lip Pigmentation Correction',headline:'Even out dark lips and reveal a healthier natural tone.',intro:'Colour-correcting pigment is used to gradually neutralise grey, brown and purple tones before building a balanced, natural-looking lip colour.',ideal:'Dark or uneven lip tone associated with sun exposure, genetics, smoking, medication or past inflammation.',process:'Skin assessment, colour analysis and often a test patch come first. Correction is gradual and generally takes 2 to 3 sessions.',healing:'Healing and pigment response are reviewed between sessions to guide each gradual correction stage.',caution:'Outcomes vary with skin depth and tone. A consultation explains what is realistic for your lips.',image:'assets/lip-blush.jpg'},
  'cheek-blush':{name:'Cheek Blush',headline:'A healthy flush that stays when the makeup is off.',intro:'Permanent cheek blush places a faint, diffused wash of colour on the apples of the cheeks for a natural, lifted-looking glow.',ideal:'Pale complexions, tired-looking skin and anyone who enjoys a fresh, subtle finish.',process:'Placement is mapped to your cheekbones and colour is kept soft and skin-tone matched.',healing:'Healing takes about a week. The colour fades softly rather than sharply as it settles.',caution:'A consultation confirms placement, shade and suitability for your skin.',image:'assets/gallery-5.jpg'},
  eyeliner:{name:'Permanent Eyeliner',headline:'Wake up with eyes already defined.',intro:'From barely-there lash enhancement to classic liner or a soft wing, permanent eyeliner creates definition at or between the lash line.',ideal:'Busy mornings, active lifestyles, contact lens wearers and anyone who struggles to apply eyeliner.',process:'Numbing is followed by fine pigment placement at the lash line in a style agreed at consultation.',healing:'Expect swelling for 24 to 48 hours and plan for no eye makeup for a week. Results typically last 2 to 5 years depending on style and skin.',caution:'Active eye infections, severe dry eye or recent eye surgery need an individual suitability check first.',image:'assets/brow-treatment.jpg'},
  'smp-men':{name:'SMP for Men',headline:'A sharper hairline and a fuller look, without surgery.',intro:'Scalp micropigmentation places thousands of tiny pigment dots to recreate the look of hair follicles. It can support a shaved-head look, receding hairline, thinning areas or transplant scars.',ideal:'Men looking for the appearance of density or a more defined hairline.',process:'The hairline is designed around age, face shape and natural growth. Density is built over 2 to 3 sessions, usually a week or two apart.',healing:'Mild redness can last 1 to 3 days. Avoid washing the scalp, sweating and sun for the first 4 days. Results generally last 4 to 6 years before a refresh.',caution:'SMP is a cosmetic density solution and does not regrow hair.',image:'assets/gallery-5.jpg'},
  'smp-women':{name:'SMP for Women',headline:'Visible scalp, softer. Thinning hair, fuller-looking.',intro:'For diffuse thinning, widening partlines, alopecia or traction hair loss, SMP creates the look of density and reduces scalp contrast while working with existing hair.',ideal:'Women wanting a discreet cosmetic solution for the look of thinning or scarring.',process:'Pigment is selected to match hair colour and texture, then applied more lightly and diffusely than many male SMP styles.',healing:'Your artist explains the individual treatment plan, aftercare and any planned build-up sessions at consultation.',caution:'SMP does not regrow hair. A consultation confirms whether it suits your type of hair loss.',image:'assets/gallery-5.jpg'},
  vitiligo:{name:'Vitiligo Camouflage',headline:'Reduce contrast. Restore confidence.',intro:'Skin-matched pigment can soften the appearance of stable vitiligo patches. Colour matching takes time, so a small test area is reviewed before treating further.',ideal:'Stable vitiligo patches where a cosmetic camouflage approach is appropriate.',process:'Consultation, stability discussion, skin matching and a small test area come before any wider treatment.',healing:'Pigment can fade or shift over time, so touch-ups may be needed.',caution:'Vitiligo should have no new or spreading patches for at least 12 months, ideally confirmed by a dermatologist.',image:'assets/pmu-service.jpg'},
  'stretch-marks':{name:'Stretch Mark Camouflage',headline:'Soften the contrast of stretch marks.',intro:'Skin-matched pigment is placed into mature, pale stretch marks to blend them with surrounding skin. It reduces visible contrast but does not remove marks or change their texture.',ideal:'Fully mature white or silvery marks, generally 1 to 2 years old.',process:'Skin assessment and tone matching guide a gradual treatment plan. Larger areas can need several sessions.',healing:'Healing and colour retention are reviewed before further sessions are planned.',caution:'This is camouflage, not removal or texture correction.',image:'assets/pmu-service.jpg'},
  scars:{name:'Scar Camouflage',headline:'Blend scars into your skin tone.',intro:'Colour-matched pigment may reduce how noticeable surgical, accident and some burn scars appear. Outcomes depend on scar type, depth and texture.',ideal:'Fully healed, stable scars assessed as suitable for cosmetic camouflage.',process:'A skin assessment and colour match are followed by a written plan. Medical clearance can be needed.',healing:'Treatment response varies and is reviewed before any additional sessions.',caution:'Scars are typically required to be stable for at least 12 months. Raised, keloid or active scars need individual assessment.',image:'assets/pmu-service.jpg'},
  areola:{name:'Areola Reconstruction',headline:'A gentle final step after breast surgery.',intro:'Areola and nipple tattooing can recreate a natural-looking areola with realistic shading and, where appropriate, 3D effects. The process is private, supportive and unhurried.',ideal:'People whose surgery and radiotherapy are complete and who have been cleared for treatment.',process:'Design and colour matching, numbing where sensation allows, then 1 to 2 sessions. A touch-up follows at 6 to 8 weeks.',healing:'Timing depends on your individual healing and surgical clearance.',caution:'Treatment commonly begins 3 to 6 months after surgery once healing is complete. Please bring your surgeon’s clearance to consultation.',image:'assets/pmu-service.jpg'}
};

